def semver_sort(versions):
    def parse_version(v):
        # Split by '+' to separate build metadata (which we ignore)
        core, _, _ = v.partition('+')

        # Split by '-' to separate pre-release
        if '-' in core:
            version_part, prerelease_part = core.split('-', 1)
        else:
            version_part = core
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        parts = version_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        prerelease_identifiers = []
        if prerelease_part:
            for identifier in prerelease_part.split('.'):
                # Check if identifier is all digits
                if identifier.isdigit():
                    prerelease_identifiers.append((0, int(identifier)))
                else:
                    prerelease_identifiers.append((1, identifier))

        return (major, minor, patch, prerelease_identifiers)

    def compare_key(item):
        idx, v = item
        major, minor, patch, prerelease = parse_version(v)

        # For sorting: versions without pre-release come after versions with pre-release
        # So we use a tuple where empty pre-release is sorted after non-empty
        if not prerelease:
            # No pre-release: sort after any pre-release of same version
            prerelease_key = (1,)  # This sorts after (0, ...)
        else:
            # Has pre-release: sort before non-pre-release
            prerelease_key = (0, tuple(prerelease))

        return (major, minor, patch, prerelease_key, idx)

    # Create list of (original_index, version) pairs to maintain stable sort
    indexed_versions = list(enumerate(versions))
    # Sort using the comparison key
    sorted_versions = sorted(indexed_versions, key=compare_key)
    # Return just the version strings
    return [v for _, v in sorted_versions]

